import React, { useState, useEffect, useCallback } from 'react';
import {
    Box,
    Typography,
    TextField,
    Button,
    List,
    ListItem,
    ListItemAvatar,
    Avatar,
    IconButton,
    CircularProgress,
    Alert,
    Divider,
    Paper,
    Collapse,
    InputAdornment
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SendIcon from '@mui/icons-material/Send';
import ReplyIcon from '@mui/icons-material/Reply';
import { commentaireService } from '../../services/commentaireService';
import { Commentaire } from '../../types';

// Styles constants
const TEXT_FIELD_FOCUS_SX = {
    '& .MuiOutlinedInput-root': {
        borderRadius: 20,
        backgroundColor: '#f0f2f5',
        '&.Mui-focused fieldset': {
            borderColor: '#773399',
            borderWidth: '2px'
        },
        '&:hover fieldset': {
            borderColor: '#773399'
        }
    }
};

const SEND_BUTTON_SX = {
    minWidth: 40,
    width: 40,
    height: 40,
    borderRadius: '50%',
    backgroundColor: '#773399',
    color: 'white',
    transition: 'all 0.3s ease',
    '&:hover': {
        backgroundColor: '#5a2a7a',
        transform: 'scale(1.05)'
    },
    '&.Mui-disabled': {
        backgroundColor: '#e4e6eb',
        color: '#b0b3b8'
    }
};

const OK_BUTTON_SX = {
    borderRadius: 6,
    backgroundColor: '#773399',
    fontFamily: 'Poppins',
    fontWeight: 600,
    fontSize: 13,
    color: 'white',
    textTransform: 'none',
    '&:hover': { backgroundColor: '#5a2a7a' }
};

const CANCEL_BUTTON_SX = {
    borderRadius: 6,
    fontFamily: 'Poppins',
    fontWeight: 600,
    fontSize: 13,
    textTransform: 'none',
    color: '#773399',
    border: '1px solid #773399',
    '&:hover': { backgroundColor: 'rgba(119, 51, 153, 0.1)' }
};

const ACTION_BUTTON_SX = {
    color: '#65676b',
    fontFamily: 'Segoe UI',
    fontSize: 13,
    fontWeight: 600,
    textTransform: 'none',
    '&:hover': {
        backgroundColor: '#f0f2f5',
        color: '#773399'
    }
};

const PAPER_SX = { 
    p: 2, 
    mt: 2,
    borderRadius: 2,
    boxShadow: 'none',
    border: '1px solid #e4e6eb'
};

const LOADING_BOX_SX = { display: 'flex', justifyContent: 'center', py: 4 };
const EMPTY_TEXT_SX = { color: '#65676b', textAlign: 'center', py: 4 };

interface CommentListProps {
    publicationId: number;
    currentUserId: number;
}

interface CommentWithReplies extends Commentaire {
    replies: CommentWithReplies[];
    showReplies: boolean;
    showReplyForm: boolean;
    level?: number;
}

const CommentList: React.FC<CommentListProps> = ({ publicationId, currentUserId }) => {
    const [comments, setComments] = useState<CommentWithReplies[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [newComment, setNewComment] = useState('');
    const [sending, setSending] = useState(false);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [editText, setEditText] = useState('');
    const [replyText, setReplyText] = useState<{ [key: number]: string }>({});
    const [replyingTo, setReplyingTo] = useState<number | null>(null);
    const [sendingReply, setSendingReply] = useState<number | null>(null);

    const isEditing = editingId !== null;

    // Organiser les commentaires en arborescence
    const organizeComments = (commentsList: Commentaire[]): CommentWithReplies[] => {
        const commentMap = new Map<number, CommentWithReplies>();
        const rootComments: CommentWithReplies[] = [];

        commentsList.forEach(comment => {
            commentMap.set(comment.id, { 
                ...comment, 
                replies: [], 
                showReplies: true,
                showReplyForm: false,
                level: 0
            });
        });

        commentsList.forEach(comment => {
            const commentWithReplies = commentMap.get(comment.id)!;
            if (comment.parent_id && commentMap.has(comment.parent_id)) {
                const parent = commentMap.get(comment.parent_id)!;
                commentWithReplies.level = (parent.level || 0) + 1;
                parent.replies.push(commentWithReplies);
            } else {
                rootComments.push(commentWithReplies);
            }
        });

        const sortByDate = (items: CommentWithReplies[]) => {
            items.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
            items.forEach(item => {
                if (item.replies && item.replies.length > 0) {
                    sortByDate(item.replies);
                }
            });
        };
        sortByDate(rootComments);

        return rootComments;
    };

    const loadComments = useCallback(async () => {
        setLoading(true);
        try {
            const response = await commentaireService.getByPublicationId(publicationId);
            const commentsList = Array.isArray(response.data) ? response.data : [];
            const organizedComments = organizeComments(commentsList);
            setComments(organizedComments);
            setError(null);
        } catch (err) {
            setError("Erreur lors du chargement des commentaires");
            console.error(err);
            setComments([]);
        } finally {
            setLoading(false);
        }
    }, [publicationId]);

    useEffect(() => {
        loadComments();
    }, [publicationId, loadComments]);

    const handleAddComment = async () => {
        if (!newComment.trim()) return;
        
        setSending(true);
        try {
            await commentaireService.ajouter(currentUserId, publicationId, newComment);
            setNewComment('');
            await loadComments();
        } catch (err) {
            setError("Erreur lors de l'ajout du commentaire");
        } finally {
            setSending(false);
        }
    };

    const handleAddReply = async (parentId: number) => {
        const replyTextValue = replyText[parentId];
        if (!replyTextValue || !replyTextValue.trim()) return;
        
        setSendingReply(parentId);
        try {
            await commentaireService.ajouter(currentUserId, publicationId, replyTextValue, parentId);
            setReplyText(prev => ({ ...prev, [parentId]: '' }));
            setReplyingTo(null);
            await loadComments();
        } catch (err) {
            setError("Erreur lors de l'ajout de la réponse");
        } finally {
            setSendingReply(null);
        }
    };

    const handleEdit = async (commentId: number) => {
        if (!editText.trim()) return;
        
        try {
            await commentaireService.modifier(commentId, editText);
            setEditingId(null);
            setEditText('');
            await loadComments();
        } catch (err) {
            setError("Erreur lors de la modification");
        }
    };

    const handleDelete = async (commentId: number) => {
        if (window.confirm('Voulez-vous vraiment supprimer ce commentaire ?')) {
            try {
                await commentaireService.supprimer(commentId);
                await loadComments();
            } catch (err) {
                setError("Erreur lors de la suppression");
            }
        }
    };

    const handleCancelEdit = () => {
        setEditingId(null);
        setEditText('');
    };

    const toggleReplyForm = (commentId: number) => {
        setReplyingTo(replyingTo === commentId ? null : commentId);
        setReplyText(prev => ({ ...prev, [commentId]: '' }));
    };

    const formatDate = (dateStr: string) => {
        const date = new Date(dateStr);
        const now = new Date();
        const diff = now.getTime() - date.getTime();
        
        if (diff < 60000) return 'à l\'instant';
        if (diff < 3600000) return `il y a ${Math.floor(diff / 60000)} min`;
        if (diff < 86400000) return `il y a ${Math.floor(diff / 3600000)} h`;
        if (diff < 604800000) return `il y a ${Math.floor(diff / 86400000)} j`;
        
        return date.toLocaleDateString('fr-FR');
    };

    const getAvatarUrl = (photo_profil: string | null) => 
        photo_profil ? `http://localhost:8080/uploads/${photo_profil}` : '/icons/green.jpg';

    const countTotalComments = (commentsList: CommentWithReplies[]): number => {
        let total = commentsList.length;
        commentsList.forEach(comment => {
            if (comment.replies && comment.replies.length > 0) {
                total += countTotalComments(comment.replies);
            }
        });
        return total;
    };

    const renderComment = (comment: CommentWithReplies) => {
        const isOwner = comment.utilisateur_id === currentUserId;
        const isCommentEditing = editingId === comment.id;
        const hasReplies = comment.replies && comment.replies.length > 0;
        const isReplying = replyingTo === comment.id;
        const isSending = sendingReply === comment.id;
        const level = comment.level || 0;
        const avatarSize = level > 0 ? 32 : 40;

        return (
            <React.Fragment key={comment.id}>
                <ListItem 
                    alignItems="flex-start" 
                    sx={{ 
                        px: 0, 
                        py: 1.5,
                        alignItems: 'flex-start'
                    }}
                >
                    <ListItemAvatar sx={{ minWidth: avatarSize + 8 }}>
                        <Avatar 
                            src={getAvatarUrl(comment.photo_profil)} 
                            sx={{ 
                                width: avatarSize, 
                                height: avatarSize,
                                cursor: 'pointer'
                            }} 
                        />
                    </ListItemAvatar>
                    
                    <Box sx={{ flex: 1 }}>
                        {isCommentEditing ? (
                            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                                <TextField
                                    fullWidth
                                    size="small"
                                    value={editText}
                                    onChange={(e) => setEditText(e.target.value)}
                                    autoFocus
                                    multiline
                                    maxRows={4}
                                    sx={TEXT_FIELD_FOCUS_SX}
                                />
                                <Button size="small" variant="contained" onClick={() => handleEdit(comment.id)} sx={OK_BUTTON_SX}>
                                    Modifier
                                </Button>
                                <Button size="small" onClick={handleCancelEdit} sx={CANCEL_BUTTON_SX}>
                                    Annuler
                                </Button>
                            </Box>
                        ) : (
                            <>
                                <Box sx={{ 
                                    backgroundColor: '#f0f2f5', 
                                    borderRadius: 2, 
                                    p: 1.5,
                                    display: 'inline-block',
                                    width: '100%'
                                }}>
                                    <Typography variant="subtitle2" component="span" sx={{ fontWeight: 600, fontSize: 13 }}>
                                        {comment.pseudo}
                                    </Typography>
                                    <Typography variant="caption" component="div" sx={{ color: '#65676b', fontSize: 11, mb: 0.5 }}>
                                        {formatDate(comment.date)}
                                    </Typography>
                                    <Typography variant="body2" sx={{ fontSize: 14, wordBreak: 'break-word' }}>
                                        {comment.texte}
                                    </Typography>
                                </Box>
                                
                                <Box sx={{ display: 'flex', gap: 2, mt: 0.5, ml: 1 }}>
                                    <Button
                                        size="small"
                                        startIcon={<ReplyIcon sx={{ fontSize: 16 }} />}
                                        onClick={() => toggleReplyForm(comment.id)}
                                        sx={ACTION_BUTTON_SX}
                                    >
                                        Répondre
                                    </Button>
                                    {isOwner && (
                                        <>
                                            <Button
                                                size="small"
                                                startIcon={<EditIcon sx={{ fontSize: 16 }} />}
                                                onClick={() => {
                                                    setEditingId(comment.id);
                                                    setEditText(comment.texte);
                                                }}
                                                sx={ACTION_BUTTON_SX}
                                            >
                                                Modifier
                                            </Button>
                                            <Button
                                                size="small"
                                                startIcon={<DeleteIcon sx={{ fontSize: 16 }} />}
                                                onClick={() => handleDelete(comment.id)}
                                                sx={{ ...ACTION_BUTTON_SX, color: '#e41e3f' }}
                                            >
                                                Supprimer
                                            </Button>
                                        </>
                                    )}
                                </Box>
                            </>
                        )}
                        
                        {/* Formulaire de réponse */}
                        {isReplying && (
                            <Box sx={{ display: 'flex', gap: 1, mt: 2 }}>
                                <Avatar 
                                    src={getAvatarUrl(null)} 
                                    sx={{ width: 32, height: 32 }} 
                                />
                                <TextField
                                    fullWidth
                                    size="small"
                                    placeholder={`Écrire une réponse à @${comment.pseudo}...`}
                                    value={replyText[comment.id] || ''}
                                    onChange={(e) => setReplyText(prev => ({ ...prev, [comment.id]: e.target.value }))}
                                    onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && handleAddReply(comment.id)}
                                    multiline
                                    maxRows={3}
                                    disabled={isSending}
                                    sx={TEXT_FIELD_FOCUS_SX}
                                    InputProps={{
                                        endAdornment: (
                                            <InputAdornment position="end">
                                                <IconButton 
                                                    onClick={() => handleAddReply(comment.id)}
                                                    disabled={isSending || !replyText[comment.id]?.trim()}
                                                    size="small"
                                                    sx={{ color: '#773399' }}
                                                >
                                                    <SendIcon />
                                                </IconButton>
                                            </InputAdornment>
                                        )
                                    }}
                                />
                            </Box>
                        )}
                        
                        {/* Réponses imbriquées */}
                        {hasReplies && (
                            <Collapse in={true}>
                                <Box sx={{ mt: 1 }}>
                                    <List sx={{ p: 0 }}>
                                        {comment.replies!.map(reply => renderComment(reply))}
                                    </List>
                                </Box>
                            </Collapse>
                        )}
                    </Box>
                </ListItem>
                <Divider sx={{ my: 0.5 }} />
            </React.Fragment>
        );
    };

    const totalComments = countTotalComments(comments);

    return (
        <Paper sx={PAPER_SX}>
            <Typography variant="h6" sx={{ fontWeight: 600, fontSize: 18, mb: 2 }}>
                Commentaires ({totalComments})
            </Typography>
            
            {error && (
                <Alert severity="error" sx={{ mb: 2, borderRadius: 2 }} onClose={() => setError(null)}>
                    {error}
                </Alert>
            )}
            
            {/* Formulaire d'ajout principal - style Facebook */}
            <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
                <Avatar 
                    src={getAvatarUrl(null)} 
                    sx={{ width: 40, height: 40 }} 
                />
                <TextField
                    fullWidth
                    size="small"
                    placeholder="Écrire un commentaire..."
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && handleAddComment()}
                    disabled={sending || isEditing}
                    multiline
                    maxRows={4}
                    sx={TEXT_FIELD_FOCUS_SX}
                    InputProps={{
                        endAdornment: (
                            <InputAdornment position="end">
                                <IconButton 
                                    onClick={handleAddComment}
                                    disabled={sending || !newComment.trim() || isEditing}
                                    sx={SEND_BUTTON_SX}
                                >
                                    {sending ? <CircularProgress size={20} color="inherit" /> : <SendIcon />}
                                </IconButton>
                            </InputAdornment>
                        )
                    }}
                />
            </Box>
            
            {/* Liste des commentaires */}
            {loading ? (
                <Box sx={LOADING_BOX_SX}>
                    <CircularProgress sx={{ color: '#773399' }} />
                </Box>
            ) : comments.length === 0 ? (
                <Typography sx={EMPTY_TEXT_SX}>
                    Aucun commentaire pour cette publication
                </Typography>
            ) : (
                <List sx={{ p: 0 }}>
                    {comments.map(comment => renderComment(comment))}
                </List>
            )}
        </Paper>
    );
};

export default CommentList;
